custom_css:
/*

主题：薄荷巧克力
作者：棺材里好冷

完全免费分享
不限制非商业化的二传、二创、二改
禁止商业化
如果这个主题是你购买的到的请用仅退款保障自己的权益

 */

/* 01 / 快速调节：只改本段即可，下方不会再覆盖这里的值。
 * 正文、斜体、引号、聊天底色、双方消息底色、边框颜色也可直接在「用户设置 → 主题颜色」里调。
 * 下方调色板覆盖主要底色、描边与浅色填充；部分叠色、阴影和 SVG 插画内的颜色为固定值。 */
:root {
  --mc-mint: #bfded0;
  --mc-mint-pale: #e9f2e7;
  --mc-leaf: #71a68b;
  --mc-green: #39745f;
  --mc-cocoa: #694537;
  --mc-ink: var(--SmartThemeBodyColor, #4b332a); /* 跟随「主文本颜色」 */
  --mc-cream: #fff9ec;
  --mc-milk: #fffdf5;
  --mc-muted: #786957;
  --mc-line: #bdc8b5;
  --mc-line-soft: #dbe2ce;   /* 虚线分隔 */
  --mc-line-strong: #b1c4ac; /* 输入框、按钮、标签描边 */
  --mc-mint-soft: #deead6;   /* 浅薄荷填充：标题条、悬停、选中 */
  --mc-wallpaper: #c6dfd1;
  --mc-danger: #a45141;
  --mc-off: var(--mc-green); /* 未开启的条目 / 复选项：深薄荷绿 */
  --mc-on: var(--mc-cocoa);  /* 已开启的条目 / 复选项：巧克力色 */
  --mc-off-opacity: .78;     /* 未开启项额外变淡，不只靠颜色区分；1 = 不变淡 */
  --mc-wallpaper-opacity: 1; /* 1：薄荷格纹墙纸（会盖住「背景」面板选的图）；0：露出酒馆原背景 */
  --mc-stickers-opacity: 1;  /* 0：关闭电脑两侧贴纸 */
  --mc-header-show: 1;       /* 0：隐藏聊天顶部主题题字（手机端同样生效） */
  --mc-avatar-scale: 1;      /* 聊天头像缩放，如 1.2 放大、0.8 缩小（各屏宽按比例） */
  --mc-card-grain: var(--mc-art-grain); /* 设为 none 可关闭消息卡纸颗粒，低端手机滚动更流畅 */
  --mc-animation-speed: 1.8s;
  --mc-line-height: 1.85;
  --mc-reading-font: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  --mc-input-note: "添一点薄荷，写下此刻的故事……";
  --mc-offline-note: "甜品铺准备中 · 请先连接 API";
  --mc-more-note: "翻一页 · 再尝一口甜";

  /* 以下为内部变量，随屏宽自动变化，一般不用改 */
  --mc-header-base: 132px;
  --mc-avatar-base: 54px;
  --mc-header-height: calc(var(--mc-header-base) * var(--mc-header-show));
  --mc-avatar-size: calc(var(--mc-avatar-base) * var(--mc-avatar-scale));
  --mc-shadow: 0 5px 14px #4b332a0b;
  --mc-checker: conic-gradient(from 90deg, var(--mc-mint) 25%, var(--mc-cream) 0 50%, var(--mc-mint) 0 75%, var(--mc-cream) 0);
  --mainFontFamily: var(--mc-reading-font);
  --mes-right-spacing: 16px;
}

/* 02 / 薄荷方格桌布与包装贴纸。装饰不接收点击。 */
body { background-color: var(--mc-mint); color-scheme: light; }
body::before {
  content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
  opacity: var(--mc-wallpaper-opacity);
  background: var(--mc-art-grain) 0 0 / 120px 120px repeat,
    var(--mc-art-sprinkle) 0 0 / 260px 260px repeat,
    repeating-linear-gradient(0deg, transparent 0 31px, #fff9ec58 31px 33px, transparent 33px 64px),
    repeating-linear-gradient(90deg, transparent 0 31px, #fff9ec58 31px 33px, transparent 33px 64px),
    var(--mc-wallpaper);
}
@media (min-width: 1101px) {
  body::after {
    /* 贴纸宽度随聊天区两侧留白缩放（最大 180px），留白不足时宽度为 0，不会被聊天区挡住半张。 */
    --mc-gutter: calc((100vw - var(--sheldWidth, 60vw)) / 2);
    --mc-sticker-w: clamp(0px, calc(var(--mc-gutter) - 24px), 180px);
    --mc-sticker-x: calc((var(--mc-gutter) - var(--mc-sticker-w)) / 2);
    content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
    opacity: var(--mc-stickers-opacity);
    background: var(--mc-art-leftSticker) left var(--mc-sticker-x) top 28% / var(--mc-sticker-w) auto no-repeat,
      var(--mc-art-rightSticker) right var(--mc-sticker-x) top 32% / var(--mc-sticker-w) auto no-repeat;
  }
}
::selection { background: var(--mc-mint); color: var(--mc-ink); }

/* 03 / 顶栏：巧克力格纹、滴落边缘和九枚功能图标。快速界面模式也保留淋面。 */
#top-bar, body.no-blur #top-bar {
  width: 100%; border: 0; border-radius: 0; box-shadow: none;
  background-color: var(--mc-cocoa) !important;
  background-image: repeating-linear-gradient(90deg, transparent 0 23px, #fff9ec0c 23px 46px),
    repeating-linear-gradient(0deg, transparent 0 22px, #341d1818 22px 44px) !important;
}
#top-bar::after {
  /* 滴落素材 240×36，显示尺寸必须保持 20:3（160×24、140×21），否则接缝处会露出细缝。 */
  content: ""; position: absolute; left: 0; right: 0; top: calc(100% - 1px); height: 24px;
  background: var(--mc-art-drip) left top / 160px 24px repeat-x; pointer-events: none;
}
/* 每种原生导航按钮只替换插画，不接管显示隐藏与点击。 */
:is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle > .drawer-icon {
  position: relative; width: 40px; height: 34px; padding: 0; border: 1px solid #fff9ec40;
  border-radius: 8px 8px 11px 11px; background-color: var(--mc-cream);
  background-position: center; background-size: 28px 28px; background-repeat: no-repeat;
  opacity: .93; filter: none;
  transition: transform .25s cubic-bezier(.2,.8,.3,1.4), background-color .2s;
}
:is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle > .drawer-icon::before { content: "" !important; }
#ai-config-button .drawer-icon { background-image: var(--mc-art-tune); }
#sys-settings-button .drawer-icon { background-image: var(--mc-art-plug); }
#advanced-formatting-button .drawer-icon { background-image: var(--mc-art-recipe); }
#WI-SP-button .drawer-icon { background-image: var(--mc-art-worldbook); }
#user-settings-button .drawer-icon { background-image: var(--mc-art-settings); }
#backgrounds-button .drawer-icon { background-image: var(--mc-art-wrapper); }
#extensions-settings-button .drawer-icon { background-image: var(--mc-art-puzzle); }
#persona-management-button .drawer-icon { background-image: var(--mc-art-persona); }
#rightNavHolder .drawer-icon { background-image: var(--mc-art-characters); }
#top-settings-holder .drawer-icon:hover { transform: translateY(-2px) rotate(-4deg); opacity: 1; }
#top-settings-holder .drawer-toggle > .drawer-icon.openIcon {
  opacity: 1; background-color: var(--mc-mint-pale); box-shadow: inset 0 -3px var(--mc-cocoa);
  outline: 1px solid var(--mc-cream); outline-offset: 2px;
}
#top-settings-holder .drawer-icon:focus-visible { outline: 2px solid var(--mc-green); outline-offset: 3px; }
#API-status-top.fa-plug-circle-exclamation::after {
  content: "!"; position: absolute; right: -3px; top: -3px; width: 13px; height: 13px;
  display: grid; place-items: center; border-radius: 50%; background: #a64f3d;
  color: var(--mc-cream); font: bold 10px/1 sans-serif; border: 1px solid var(--mc-cream);
}

/* 04 / 聊天：奶油卡纸、薄荷格纹胶带与巧克力淋面。 */
#chat {
  min-height: 0; border: 0; background: var(--SmartThemeChatTintColor, #f8f6e9ee); padding: 24px 18px 24px; /* 顶部让出顶栏滴落的高度 */
  box-shadow: inset 1px 0 #fffdf5, inset -1px 0 #fffdf5; backdrop-filter: none;
}
body.no-blur #chat { background-color: var(--SmartThemeChatTintColor, #f8f6e9) !important; }
#chat:has(.mes)::before {
  /* 手机端 #chat 的子项不自动拉伸，必须写明宽度，否则题字宽度为 0 */
  content: ""; display: block; align-self: stretch; width: 100%; flex: 0 0 var(--mc-header-height); height: var(--mc-header-height);
  background: var(--mc-art-wordmark) center / min(100%, 600px) auto no-repeat;
  pointer-events: none;
}
#chat .mes { padding: 14px 0 10px; gap: 13px; background: transparent; border: 0; flex-shrink: 0; }
#chat .mes.selected { background: #e6b5b850; outline: 2px dashed #a45f57; outline-offset: -2px; border-radius: 12px; }
body:not(.bubblechat):not(.documentstyle) #chat .mes:not(.smallSysMes) .mes_block {
  position: relative; min-width: 0; margin: 0; padding: 30px 22px 26px;
  border: 1px solid var(--SmartThemeBorderColor, var(--mc-line)); border-radius: 12px 12px 16px 5px;
  background: var(--mc-card-grain) 0 0 / 120px 120px repeat, var(--SmartThemeBotMesBlurTintColor, var(--mc-cream));
  box-shadow: var(--mc-shadow), inset 0 0 0 4px var(--mc-milk), inset 0 0 0 5px var(--mc-line-soft);
}
body:not(.bubblechat):not(.documentstyle) #chat .mes:not(.smallSysMes) .mes_block::before {
  content: ""; position: absolute; top: -1px; left: -1px; right: -1px; height: 21px;
  background: var(--mc-art-drip) 0 0 / 140px 21px repeat-x;
  border-radius: 12px 12px 0 0; pointer-events: none;
}
body:not(.bubblechat):not(.documentstyle) #chat .mes:not(.smallSysMes) .mes_block::after {
  content: ""; position: absolute; right: 19px; bottom: 8px; width: 41px; height: 11px;
  background: var(--mc-checker) 0 0 / 11px 11px; opacity: .9; transform: rotate(-4deg); pointer-events: none;
}
body:not(.bubblechat):not(.documentstyle) #chat .mes[is_user="true"]:not(.smallSysMes) .mes_block {
  background-color: var(--SmartThemeUserMesBlurTintColor, var(--mc-mint-pale)); border-color: #9bbb9f; border-radius: 12px 12px 5px 16px;
  box-shadow: var(--mc-shadow), inset 0 0 0 4px #f7fbef, inset 0 0 0 5px #c9ddc4;
}
body:not(.bubblechat):not(.documentstyle) #chat .mes[is_user="true"]:not(.smallSysMes) .mes_block::before {
  height: 13px; top: 0; left: 0; right: 0; background: var(--mc-checker) 0 0 / 26px 26px;
  border-bottom: 1px solid #b9d2bc;
}
body:not(.bubblechat):not(.documentstyle) #chat .mes[is_user="true"]:not(.smallSysMes) .mes_block::after {
  background: var(--mc-art-leaf) center / contain no-repeat; width: 27px; height: 22px; right: 18px; bottom: 5px;
}
body:not(.bubblechat):not(.documentstyle) #chat .mes.last_mes:not(.smallSysMes) .mes_block::after,
body.swipeAllMessages:not(.bubblechat):not(.documentstyle) #chat .mes:not(.smallSysMes) .mes_block::after { right: 70px; }

/* 头像：真正的 1:1 方框（角色列表同样为方形）。 */
.avatar, .avatar img { border-radius: 0 !important; }
.avatar img { object-fit: cover; }
#chat .mes .mesAvatarWrapper { padding-top: 5px; flex: 0 0 auto; }
#chat .mes .avatar { position: relative; overflow: visible; }
#chat .mes .avatar, #chat .mes .avatar img {
  width: var(--mc-avatar-size) !important; height: var(--mc-avatar-size) !important; aspect-ratio: 1;
}
#chat .mes .avatar img {
  box-sizing: border-box; border: 3px solid var(--mc-cream);
  box-shadow: 0 0 0 2px var(--mc-cocoa), 0 0 0 5px #bfded090;
}
#chat .mes[is_user="true"] .avatar img { box-shadow: 0 0 0 2px var(--mc-green), 0 0 0 5px #bfded090; }
#chat .mes .avatar::after {
  content: ""; position: absolute; right: -8px; top: -10px; width: 24px; height: 24px;
  background: var(--mc-art-leaf) center / contain no-repeat; pointer-events: none; transform: rotate(16deg);
}
#chat .mes[is_user="true"] .avatar::after { background-image: var(--mc-art-cherry); width: 27px; height: 27px; }

#chat .mes .name_text { color: var(--mc-cocoa); font-weight: 700; letter-spacing: .06em; }
#chat .mes[is_user="true"] .name_text { color: var(--mc-green); }
#chat .mes .ch_name { margin-bottom: 10px; padding-bottom: 8px; border-bottom: 1px dashed var(--mc-line-soft); gap: 5px; }
#chat .mes .timestamp { color: var(--mc-muted); font-size: .68em; opacity: .9; }
#chat .mes :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) { color: var(--mc-muted); font-size: .65em; opacity: .85; font-weight: 400; }
#chat .mes .mesIDDisplay { margin-top: 9px; }
.mes_text { color: var(--mc-ink); font-family: var(--mc-reading-font); font-weight: 400; line-height: var(--mc-line-height); letter-spacing: .025em; overflow-wrap: break-word; }
.mes_text em { color: var(--SmartThemeEmColor, #697557); }
.mes_text strong { color: var(--mc-cocoa); font-weight: 700; }
.mes_text :is(q, .quote), .mes_reasoning q { color: var(--SmartThemeQuoteColor, var(--mc-green)); }
.mes_text u { text-decoration: underline wavy #c79c9a; text-underline-offset: 4px; }
.mes_text a { color: var(--mc-green); text-decoration-color: #98b9a1; text-underline-offset: 3px; }
.mes_text :is(h1,h2,h3,h4) { color: var(--mc-cocoa); line-height: 1.45; }
.mes_text li::marker { color: var(--mc-leaf); }
.mes_text blockquote {
  margin: .7em 0; padding: .6em 1em; background: #bfded040;
  color: #456650; border-left: 3px solid var(--mc-leaf); border-radius: 2px 9px 9px 2px;
}
.mes_text code { color: #715043; background: #eadbc955; border: 1px solid #d9cbb8; border-radius: 4px; padding: .08em .3em; }
.mes_text pre { max-width: 100%; overflow-x: auto; border: 1px solid #d9cbb8; background: #f3ecde; border-radius: 8px; }
.mes_text pre code { border: 0; background: transparent; }
.mes_text hr { height: 24px; border: 0; opacity: 1; background: var(--mc-art-divider) center / min(100%, 340px) 24px no-repeat; }
.mes_text :is(th,td) { border: 1px solid var(--mc-line); padding: .45em .6em; }
.mes_text th { background: #bfded080; color: var(--mc-ink); }
.mes_text table { max-width: 100%; }
.mes_text :is(img,video,iframe) { max-width: 100%; }
.mes_text details { margin: .7em 0; padding: .5em .9em; border: 1px dashed var(--mc-line-strong); background: #fffdf590; border-radius: 8px; }
.mes_text details > summary { color: var(--mc-green); cursor: pointer; font-weight: 600; }
.mes_text details[open] > summary { margin-bottom: .6em; padding-bottom: .5em; border-bottom: 1px dashed var(--mc-line-soft); }
.mes_text details[open] { border-style: solid; }
.mes_reasoning_header { position: relative; color: var(--mc-green); background: var(--mc-mint-soft); border: 1px dashed var(--mc-line-strong); border-radius: 7px; padding: 7px 25px 7px 34px; }
.mes_reasoning_header::before { content: ""; position: absolute; left: 8px; top: 50%; width: 19px; height: 19px; transform: translateY(-50%); background: var(--mc-art-leaf) center / contain no-repeat; }
.mes_reasoning { color: #687257; background: #eff2e780; border-left: 2px solid #a6c5ae; border-radius: 0 7px 7px 0; line-height: 1.75; }
.mes_reasoning_details[data-state="thinking"] .mes_reasoning_header { border-style: solid; border-color: var(--mc-green); }
.mes_button, .extraMesButtons > div { color: #846754; opacity: .8; filter: none; }
.mes_button:hover, .extraMesButtons > div:hover { color: var(--mc-green); opacity: 1; }
.swipe_left, .swipe_right, .swipes-counter { color: var(--mc-green); }
.swipes-counter { background: var(--mc-cream); border: 1px solid var(--mc-line-strong); border-radius: 10px; opacity: .9; }
/* 生成中最后一条（常是用户消息）的计数还没填字，空的时候不画胶囊，免得出现一个空框。 */
.swipes-counter:empty { background: none; border-color: transparent; }
.edit_textarea, .reasoning_edit_textarea { background: var(--mc-milk) !important; color: var(--mc-ink) !important; border: 1px dashed var(--mc-green) !important; line-height: 1.8; }
#chat .mes.smallSysMes { color: var(--mc-muted); border: 1px dashed var(--mc-line-strong); border-radius: 7px; background: #fff9eca0; margin: 8px 0; }
#show_more_messages {
  font-size: 0; align-self: center; margin: 4px auto 8px; padding: 8px 21px;
  border: 1px solid var(--mc-line-strong); border-radius: 30px; background: var(--mc-cream); box-shadow: 0 2px 0 #a4bc9e40; cursor: pointer;
}
#show_more_messages::before { content: var(--mc-more-note); color: var(--mc-green); font: 12px/1.5 var(--mc-reading-font); letter-spacing: .12em; }
#show_more_messages:hover { background: var(--mc-mint-soft); }

/* 05 / 输入区：格纹封口、薄荷叶封签、甜品按钮。保持原生连接/生成状态。 */
#form_sheld { padding: 9px 10px max(9px, env(safe-area-inset-bottom)); background: var(--SmartThemeChatTintColor, #f8f6e9ee); flex-shrink: 0; }
#send_form {
  position: relative; border: 1px solid var(--mc-line-strong); border-radius: 12px; padding: 11px 6px 3px;
  background: var(--mc-milk); box-shadow: 0 3px 0 #abc3a536; backdrop-filter: none;
  transition: box-shadow .25s, border-color .25s;
}
body.no-blur #send_form { background-color: var(--mc-milk) !important; }
#send_form::before { content: ""; position: absolute; inset: 0 0 auto; height: 7px; border-radius: 11px 11px 0 0; background: var(--mc-checker) 0 0 / 16px 16px; pointer-events: none; }
#send_form::after {
  content: ""; position: absolute; top: -13px; left: calc(50% - 16px); width: 32px; height: 25px;
  background: var(--mc-art-leaf) center / contain no-repeat; pointer-events: none;
  transition: transform .4s cubic-bezier(.2,.8,.3,1.4);
}
#send_form.no-connection { border-style: dashed; border-color: #ad7764; }
/* 聚焦时只用主题自己的薄荷光圈，去掉酒馆原生的 1px 外框，避免双层边。 */
#send_form:focus-within, #send_form:has(#send_textarea:focus-visible) {
  border-color: var(--mc-green); outline: none;
  box-shadow: 0 0 0 3px #bfded080, 0 4px 0 #8eaf9d30;
}
#send_form:focus-within::after { transform: rotate(-14deg) translateY(-3px); }
#send_form.no-connection::after { transform: rotate(17deg); }
body[data-generating="true"] #send_form::after { animation: mc-leaf-rock 1.3s ease-in-out infinite; }
#send_textarea { color: var(--mc-ink); font-family: var(--mc-reading-font); line-height: 1.6; background: transparent; border: 0; border-top: var(--progWidth, 0px) solid var(--progColor, var(--mc-leaf)); box-shadow: none; }

/* 自定义提示文案只在支持 :has() 时替换原生占位符；旧浏览器继续显示原生提示。
 * 以输入行（而非含快速回复栏的整个输入框）为参照居中。 */
#nonQRFormItems { position: relative; }
@supports selector(:has(*)) {
  #send_form #send_textarea::placeholder {
    color: transparent !important; -webkit-text-fill-color: transparent !important; opacity: 0 !important;
  }
  #nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--mc-input-note); position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
    width: max-content; max-width: calc(100% - 184px); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    text-align: center; color: var(--mc-off); pointer-events: none;
    font: 12px/1.5 var(--mc-reading-font); letter-spacing: .03em;
  }
  #nonQRFormItems:has(#send_textarea:focus)::before { opacity: .5; } /* 聚焦后淡化保留，开始输入才消失 */
  #send_form.no-connection #nonQRFormItems:has(#send_textarea:placeholder-shown)::before { content: var(--mc-offline-note); color: #975643; }
}

/* 左侧：打开菜单 = 甜品菜单；扩展 = 加料巧克力盒。 */
#leftSendForm { gap: 3px; }
#leftSendForm > div, #rightSendForm > div { color: var(--mc-cocoa); }
#leftSendForm :is(#options_button,#extensionsMenuButton) {
  position: relative; width: 38px; height: 44px; flex: 0 0 38px;
  font-size: 0; color: var(--mc-cocoa); opacity: 1; filter: none;
  background-color: transparent; background-repeat: no-repeat;
  background-position: center; background-size: 31px 31px;
  transition: transform .25s cubic-bezier(.2,.8,.3,1.4), background-color .2s;
}
#options_button { background-image: var(--mc-art-menu); }
#extensionsMenuButton { background-image: var(--mc-art-bonbons); }
#leftSendForm :is(#options_button,#extensionsMenuButton)::before { content: "" !important; }
#extensionsMenuButton > i { opacity: 0; }
#leftSendForm #options_button:hover { transform: rotate(-8deg) translateY(-3px); }
#leftSendForm #extensionsMenuButton:hover { animation: mc-box-rock .5s ease; }
#leftSendForm :is(#options_button,#extensionsMenuButton):active { transform: scale(.9); }

/* 右侧：蛋糕发送、甜点罩停止；「继续」= 再来一块马卡龙，「代写」= 薄荷叶羽毛笔。 */
#rightSendForm { min-width: 48px; flex-shrink: 0; }
#rightSendForm > #send_but {
  position: relative; width: 48px; height: 48px; flex-shrink: 0; opacity: 1;
  background: var(--mc-art-cake) center / 44px 44px no-repeat;
  transform-origin: center 85%; transition: transform .25s cubic-bezier(.2,.8,.3,1.4), filter .2s;
}
#rightSendForm > #send_but::before { content: ""; }
/* 输入内容后蛋糕轻跳两下提示「可以发送」，之后保持静止。 */
#send_form:not(.no-connection):has(#send_textarea:not(:placeholder-shown)) #send_but {
  animation: mc-cake-ready var(--mc-animation-speed) ease-in-out 2;
}
#rightSendForm > #send_but:hover {
  animation: none !important; transform: translateY(-5px) rotate(-9deg);
  filter: drop-shadow(0 4px 2px #69453725);
}
#rightSendForm > #send_but:active { transform: translateY(2px) scale(.85,.8); }
#send_but::after {
  content: "✦"; position: absolute; top: -3px; right: 0; color: var(--mc-green);
  font: 15px/1 Georgia,serif; opacity: 0; pointer-events: none; transition: opacity .2s, transform .2s;
}
#send_but:hover::after { opacity: 1; transform: translateY(-4px) rotate(22deg); }
#rightSendForm > :is(#mes_continue, #mes_impersonate) {
  width: 40px; height: 44px; flex-shrink: 0; font-size: 0; opacity: .92; filter: none;
  background: center / 34px 34px no-repeat;
  transition: transform .25s cubic-bezier(.2,.8,.3,1.4), opacity .2s;
}
#rightSendForm > :is(#mes_continue, #mes_impersonate)::before { content: "" !important; }
#rightSendForm > #mes_continue { background-image: var(--mc-art-continue); }
#rightSendForm > #mes_impersonate { background-image: var(--mc-art-impersonate); }
#rightSendForm > :is(#mes_continue, #mes_impersonate):hover { opacity: 1; filter: none; transform: translateY(-3px) rotate(-6deg); }
#rightSendForm > :is(#mes_continue, #mes_impersonate):active { transform: scale(.9); }
#rightSendForm > #mes_stop {
  position: relative; width: 48px; height: 48px; padding: 0; border: 0; border-radius: 0; opacity: 1;
  background: var(--mc-art-stop) center / 44px 44px no-repeat;
}
#mes_stop > i { opacity: 0; }
#rightSendForm > #mes_stop:hover { transform: scale(1.06); }
body[data-generating="true"] #mes_stop { animation: mc-cloche 1.8s ease-in-out infinite; }
body[data-generating="true"] #chat .last_mes:not([is_user="true"]) .avatar::after { animation: mc-leaf-rock 1.3s ease-in-out infinite; }
/* 未连接装饰只在原生发送键隐藏时出现；不制造可点击的假按钮。 */
#send_form.no-connection #rightSendForm::after {
  content: ""; width: 48px; height: 48px; flex: 0 0 48px; align-self: center;
  pointer-events: none; background: var(--mc-art-offline) center / 44px 44px no-repeat;
}
:is(#leftSendForm, #rightSendForm) > :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate):focus-visible {
  outline: 2px solid var(--mc-green); outline-offset: 3px;
}

/* 06 / 设置抽屉、世界书、角色面板及弹窗。 */
.drawer-content, #character_popup, #world_popup, .popup,
#options .options-content, #extensionsMenu {
  color: var(--mc-ink); background-color: var(--SmartThemeBlurTintColor, var(--mc-cream));
  border: 1px solid var(--SmartThemeBorderColor, var(--mc-line)) !important; box-shadow: 0 12px 35px #4b332a26, inset 0 0 0 3px var(--mc-milk);
  border-radius: 12px;
}
.drawer-content, #character_popup, #world_popup, .popup {
  background-image: var(--mc-checker); background-size: 24px 10px; background-repeat: repeat-x; background-position: left top;
}
.drawer-content :is(h2,h3,h4), .popup :is(h2,h3,h4) { color: var(--mc-cocoa); }
.standoutHeader, #user-settings-block h4,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
  color: var(--mc-cocoa); background: var(--mc-mint-soft); border: 1px solid var(--mc-line-strong); border-left: 4px solid var(--mc-leaf);
  border-radius: 4px 9px 9px 4px; padding: 7px 9px; box-shadow: none;
}
.inline-drawer-icon { color: var(--mc-green); }
.inline-drawer:has(> .inline-drawer-content[style*="block"]) > .inline-drawer-header {
  color: var(--mc-cocoa); background-color: #cde2d4; border-color: #94b8a4;
}
#options .options-content a, #extensionsMenu > div, .list-group-item { color: var(--mc-ink); border-radius: 5px; }
#options .options-content a:hover, #extensionsMenu > div:hover, .list-group-item:hover { background-color: var(--mc-mint-soft); }
.text_pole, select, textarea:not(#send_textarea), input:is(:not([type]),[type="text"],[type="number"],[type="search"],[type="password"],[type="url"],[type="email"]) {
  color: var(--mc-ink); background-color: var(--mc-milk); border: 1px solid var(--mc-line-strong); border-radius: 7px;
}
select option { color: var(--mc-ink); background-color: var(--mc-cream); }
:is(.text_pole, select, textarea, input):focus-visible { outline: 2px solid var(--mc-green); outline-offset: 2px; }
.menu_button {
  color: var(--mc-cocoa); background: var(--mc-milk); border: 1px solid var(--mc-line-strong); border-radius: 7px;
  box-shadow: 0 2px 0 #bed2b640; filter: none; transition: background-color .15s ease;
}
.menu_button:not(.disabled):not([disabled]):hover { background: var(--mc-mint-soft); color: var(--mc-green); border-color: var(--mc-leaf); }
.menu_button.toggleable.toggled, .menu_button.active {
  color: var(--mc-cocoa) !important; background: var(--mc-mint) !important; border-color: var(--mc-cocoa) !important;
}
/* 危险操作：悬停时保持红色，只加深一点。 */
/* 酒馆给 .redWarningBG 写了 !important 的深红，这里同样加 !important 才能换成主题的莓果红。 */
#dialogue_del_mes_ok, .mes_edit_delete.menu_button, .redWarningBG { color: var(--mc-cream); background-color: var(--mc-danger) !important; border-color: #914535; }
:is(#dialogue_del_mes_ok, .mes_edit_delete.menu_button, .redWarningBG):not(.disabled):not([disabled]):hover {
  color: var(--mc-cream); background-color: #8d4335 !important; border-color: #7a382c;
}
input[type="checkbox"], input[type="radio"] { accent-color: var(--mc-cocoa); filter: none; }
input[type="checkbox"] { border-color: var(--mc-leaf); background-color: var(--mc-milk); }
input[type="checkbox"]:checked { background-color: var(--mc-cocoa); border-color: var(--mc-cocoa); }
input[type="checkbox"]::before { box-shadow: inset 1em 1em var(--mc-cream); }
input[type="range"], input.neo-range-slider { accent-color: var(--mc-green); background: #bdd4b9 !important; border-radius: 5px; box-shadow: none !important; filter: none; }
input[type="range"]::-webkit-slider-thumb { background: var(--mc-cocoa); border: 2px solid var(--mc-cream); border-radius: 5px; box-shadow: 0 0 0 1px #ad8f75; }
input[type="range"]::-moz-range-thumb { background: var(--mc-cocoa); border: 2px solid var(--mc-cream); border-radius: 5px; }
.select2-container .select2-selection, .select2-dropdown { background: var(--mc-milk) !important; color: var(--mc-ink); border-color: var(--mc-line-strong) !important; border-radius: 7px; }
.select2-container .select2-selection--multiple .select2-selection__choice { background: var(--mc-mint-soft); color: var(--mc-ink); border-color: var(--mc-line-strong); border-radius: 5px; }
.select2-container--default .select2-selection--single .select2-selection__rendered { color: var(--mc-ink); }
.select2-results__option--highlighted { background: var(--mc-mint-soft) !important; color: var(--mc-ink) !important; }
.character_select, .group_select, .bogus_folder_select, .recentChat { border-radius: 8px; }
.character_select:hover, .group_select:hover, .bogus_folder_select:hover, .recentChat:hover { background-color: var(--mc-mint-soft); }
.character_select.is_fav .ch_name, .group_select.is_fav .ch_name { color: var(--mc-green); }
.tag { color: var(--mc-ink); background: var(--mc-mint-soft); border-color: var(--mc-line-strong); border-radius: 5px; }
.tag[style*="background-color"]:not([style^="color"]):not([style*="; color"]):not([style*=";color"]) { color: #fffdf5; text-shadow: 0 1px 2px #302016; }
.qr--button { color: var(--mc-cocoa); background: var(--mc-mint-soft); border: 1px solid var(--mc-line-strong); border-radius: 6px; }

/* 开关状态：开启 = 巧克力；关闭 = 深薄荷并略微变淡（颜色 + 浓淡双重区分，色弱也能分清）。
 * 世界书的关闭条目酒馆本身已做半透明 + 去色，这里只换颜色。 */
.world_entry:not(.disabledWIEntry) { color: var(--mc-on); }
.world_entry.disabledWIEntry { color: var(--mc-off); background-color: #eaf3eb; }
.checkbox_label:has(input:checked) > span { color: var(--mc-on); }
.checkbox_label:has(input:not(:checked)) > span { color: var(--mc-off); opacity: var(--mc-off-opacity); }

/* 预设管理器：开启 = 巧克力实线；关闭 = 深薄荷虚线并变淡；名称、token、操作符都覆盖。 */
#completion_prompt_manager #completion_prompt_manager_list {
  background: #f3f3e6; border: 1px solid var(--mc-line); border-radius: 6px; padding: 7px;
}
#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--mc-cocoa) !important; background: #e0ecde;
  border-bottom: 1px dashed #a7c5b4; opacity: 1 !important; text-shadow: none;
}
#completion_prompt_manager .completion_prompt_manager_header :is(span,div) {
  color: inherit !important; opacity: 1 !important; text-shadow: none;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt {
  --mc-state-ink: var(--mc-on);
  color: var(--mc-state-ink) !important;
  background-color: var(--mc-cream) !important;
  border: 1px solid #c9b3a0 !important; border-left: 4px solid var(--mc-cocoa) !important;
  border-radius: 5px; margin-block: 5px; opacity: 1 !important; filter: none !important;
  transition: background-color .18s, border-color .18s;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  --mc-state-ink: var(--mc-off);
  background-color: #eaf3eb !important;
  border: 1px dashed #90baa8 !important; border-left: 4px solid #9fc8b8 !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt :is(
  .completion_prompt_manager_prompt_name, .completion_prompt_manager_prompt_name a,
  .completion_prompt_manager_prompt_name span, .completion_prompt_manager_prompt_name small,
  .prompt-manager-inspect-action, .prompt_manager_prompt_tokens,
  .prompt_manager_prompt_controls, .prompt_manager_prompt_controls span, .drag-handle
) {
  color: var(--mc-state-ink) !important; opacity: 1 !important;
  filter: none !important; text-shadow: none !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled :is(.completion_prompt_manager_prompt_name, .prompt_manager_prompt_tokens) {
  opacity: var(--mc-off-opacity) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:hover { background-color: #f4efdf !important; }
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled:hover { background-color: #dceee2 !important; }

/* 提示消息：成功 = 薄荷叶、信息 = 巧克力、警告 = 焦糖、错误 = 莓果红。 */
body #toast-container > div { color: var(--mc-ink); background-color: var(--mc-cream); background-image: none !important; padding-left: 16px; border: 1px solid var(--mc-line); border-left: 4px solid var(--mc-leaf); border-radius: 10px; opacity: 1; box-shadow: 0 7px 22px #4b332a25; }
body #toast-container > .toast-info { border-left-color: var(--mc-cocoa); }
body #toast-container > .toast-warning { border-left-color: #b18344; }
body #toast-container > .toast-error { border-left-color: var(--mc-danger); }
body #toast-container .toast-close-button { color: var(--mc-cocoa); text-shadow: none; }
body #toast-container .toast-progress { background: var(--mc-leaf); }
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-thumb { border: 1px solid #eef0df; border-radius: 5px; background: #9fbda5; box-shadow: none; }
::-webkit-scrollbar-track { background: transparent; }
@supports (-moz-appearance: none) { * { scrollbar-width: thin; scrollbar-color: #9fbda5 transparent; } }

/* 07 / 手机与平板：保留装饰，放大正文可用宽度；不锁定输入框高度。
 * 这里只改内部基准值（--mc-header-base / --mc-avatar-base），快速调节区的开关和缩放照样生效。 */
@media (max-width: 1100px) { :root { --mc-header-base: 116px; } }
@media (max-width: 1000px) {
  :root { --mc-header-base: 103px; --mc-avatar-base: 42px; --mes-right-spacing: 10px; }
  #chat { padding: 24px 9px 18px; }
  #chat .mes { gap: 9px; padding: 13px 0 8px; }
  #chat .mes .avatar img { border-width: 2px; }
  #chat .mes[is_user="true"] .avatar::after { width: 23px; height: 23px; }
  body:not(.bubblechat):not(.documentstyle) #chat .mes:not(.smallSysMes) .mes_block { padding: 26px 13px 23px; }
  #chat .mes .ch_name { flex-wrap: wrap; margin-bottom: 9px; }
  #chat .mes .ch_name .flex1 { min-width: 0; }
  #chat .mes .name_text { font-size: .92em; }
  #chat .mes .timestamp { font-size: .63em; }
  #chat .mes .ch_name > .mes_buttons { margin-left: auto; }
  #form_sheld { padding: 9px 5px max(7px, env(safe-area-inset-bottom)); }
  #send_form { padding-left: 2px; padding-right: 2px; }
  #send_textarea { font-size: max(16px, var(--mainFontSize, 16px)); }
  #nonQRFormItems:has(#send_textarea:placeholder-shown)::before { font-size: 11px; }
  #leftSendForm :is(#options_button,#extensionsMenuButton) { width: 32px; flex-basis: 32px; height: 42px; background-size: 29px 29px; }
  #rightSendForm { min-width: 42px; }
  #rightSendForm > #send_but, #rightSendForm > #mes_stop, #send_form.no-connection #rightSendForm::after {
    width: 42px; height: 42px; flex-basis: 42px; background-size: 39px 39px;
  }
  #rightSendForm > :is(#mes_continue, #mes_impersonate) { width: 34px; height: 42px; background-size: 30px 30px; }
  #top-settings-holder { gap: clamp(1px,1vw,7px); }
  :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle > .drawer-icon { width: 30px; height: 31px; background-size: 25px 25px; border-radius: 6px; }
  .drawer-content, .popup { border-radius: 8px; }
}
@media (max-width: 600px) {
  #nonQRFormItems:has(#send_textarea:placeholder-shown)::before { max-width: calc(100% - 150px); }
}
@media (max-width: 360px) {
  :root { --mc-avatar-base: 36px; }
  #chat { padding-left: 7px; padding-right: 7px; }
  #chat .mes { gap: 7px; }
  body:not(.bubblechat):not(.documentstyle) #chat .mes:not(.smallSysMes) .mes_block { padding-left: 10px; padding-right: 10px; }
  :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle > .drawer-icon { width: 27px; }
}

/* 09 / 启动页：巧克力淋面雨棚 + 薄荷格纹桌布，蛋糕在盘子上蹦蹦跳，巧克力条进度。
 * 酒馆的启动页不能加元素，全部用现成元素拼：
 *   #loader::before  主题题字        .splash-logo   蛋糕（替换酒馆 logo）
 *   #loader::after   盘子和影子      #load-spinner  巧克力条进度（替换齿轮）
 *   .splash-message  “正在初始化…” */
#preloader,
dialog.popup:has(#loader.splash-screen),
dialog.popup:has(#loader.splash-screen)::backdrop {
  background:
    linear-gradient(var(--mc-cocoa, #694537), var(--mc-cocoa, #694537)) left top / 100% 19px no-repeat,
    var(--mc-art-drip) left 0 top 18px / 160px 24px repeat-x,
    radial-gradient(ellipse 520px 440px at 50% 48%, #fff9ecf0 0 45%, #fff9ec00 100%),
    var(--mc-art-sprinkle) 0 0 / 260px 260px repeat,
    repeating-linear-gradient(0deg, transparent 0 31px, #fff9ec58 31px 33px, transparent 33px 64px),
    repeating-linear-gradient(90deg, transparent 0 31px, #fff9ec58 31px 33px, transparent 33px 64px),
    var(--mc-wallpaper, #c6dfd1) !important;
  backdrop-filter: none !important; -webkit-backdrop-filter: none !important;
}
/* 弹窗本身铺满全屏，不依赖 ::backdrop 能否读到变量 */
dialog.popup:has(#loader.splash-screen) {
  position: fixed; inset: 0; width: 100vw !important; height: 100dvh !important;
  max-width: none !important; max-height: none !important; margin: 0 !important; padding: 0 !important;
  border: 0 !important; border-radius: 0 !important; box-shadow: none !important; outline: none;
}
dialog.popup:has(#loader.splash-screen) :is(.popup-body, .popup-content) {
  width: 100%; height: 100%; max-height: none; margin: 0; padding: 0; overflow: hidden;
  background: transparent !important; border: 0 !important; box-shadow: none !important;
}
#loader.splash-screen {
  gap: 0 !important; width: 100%; height: 100%; min-height: 100dvh; padding-bottom: 4vh;
  color: var(--mc-cocoa); background: none !important;
}
#loader.splash-screen::before {
  content: ""; order: 0; width: min(440px, 84vw); aspect-ratio: 640 / 148; margin-bottom: 34px;
  background: var(--mc-art-wordmark) center / contain no-repeat;
  opacity: 0; animation: mc-sp-in .8s ease .1s forwards;
}
#loader.splash-screen .splash-logo {
  order: 1; position: relative; z-index: 1;
  width: 128px !important; height: 128px !important; max-width: none; margin: 0 !important;
  object-position: -9999px 0; filter: none !important;
  background: var(--mc-art-cake) center / contain no-repeat;
  transform-origin: 50% 92%;
  animation: mc-sp-in .6s ease .3s both, mc-sp-hop 1.3s cubic-bezier(.3,.7,.4,1) .9s infinite;
}
/* 盘子：奶油色椭圆，下方的影子跟着蛋糕一起缩放 */
#loader.splash-screen::after {
  content: ""; order: 2; width: 170px; height: 30px; margin-top: -18px;
  background:
    radial-gradient(closest-side, var(--mc-milk) 96%, #fffdf500) center 5px / 128px 15px no-repeat,
    radial-gradient(closest-side, #69453700 90%, var(--mc-cocoa) 92% 98%, #69453700) center 2px / 166px 22px no-repeat,
    radial-gradient(closest-side, var(--mc-mint) 97%, #bfded000) center 2px / 166px 22px no-repeat,
    radial-gradient(closest-side, #69453738, #69453700) center 22px / 130px 10px no-repeat;
  animation: mc-sp-in .6s ease .3s both, mc-sp-shadow 1.3s cubic-bezier(.3,.7,.4,1) .9s infinite;
}
/* 齿轮 → 巧克力条：外框巧克力色，里面薄荷条纹一格格填满 */
#loader.splash-screen #load-spinner {
  order: 3; position: relative !important; inset: auto !important;
  width: 168px !important; height: 18px !important; margin-top: 30px;
  font-size: 0 !important; color: transparent !important;
  border: 2px solid var(--mc-cocoa); border-radius: 9px; overflow: hidden;
  background: var(--mc-cream) !important; box-shadow: 0 3px 0 #69453726;
  animation: mc-sp-in .6s ease .5s both !important;
}
#loader.splash-screen #load-spinner::before {
  content: "" !important; position: absolute; left: 0; top: 0; bottom: 0; width: 8%;
  border-right: 2px solid var(--mc-cocoa); border-radius: 0 6px 6px 0;
  background: repeating-linear-gradient(-45deg, var(--mc-mint) 0 6px, var(--mc-leaf) 6px 12px) 0 0 / 34px 100%;
  animation: mc-sp-fill 2.6s ease-in-out infinite, mc-sp-stripe .8s linear infinite;
}
#loader.splash-screen .splash-message {
  order: 4; margin: 14px 0 0 !important;
  color: var(--mc-green) !important; opacity: 1 !important;
  font: 500 13px/1.6 var(--mc-reading-font) !important; letter-spacing: .24em !important;
  animation: mc-sp-in .6s ease .7s both;
}
/* 文字两侧各一片薄荷叶，轻轻摇 */
#loader.splash-screen .splash-message::before,
#loader.splash-screen .splash-message::after {
  content: ""; display: inline-block; width: 24px; height: 22px; margin: 0 8px; vertical-align: -5px;
  background: var(--mc-art-leaf) center / contain no-repeat;
  animation: mc-leaf-rock 1.6s ease-in-out infinite;
}
#loader.splash-screen .splash-message::after { transform: scaleX(-1); animation-name: mc-sp-leaf-r; animation-delay: .8s; }
@keyframes mc-sp-leaf-r { 0%,100% { transform: scaleX(-1) rotate(-8deg); } 50% { transform: scaleX(-1) rotate(8deg); } }
@keyframes mc-sp-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes mc-sp-hop {
  0%, 100% { transform: translateY(0) scale(1, 1); }
  12% { transform: translateY(0) scale(1.08, .9); }
  42% { transform: translateY(-30px) scale(.96, 1.05) rotate(-4deg); }
  62% { transform: translateY(-30px) scale(.97, 1.04) rotate(3deg); }
  84% { transform: translateY(0) scale(1.06, .93); }
}
@keyframes mc-sp-shadow {
  0%, 100%, 12%, 84% { background-size: 128px 15px, 166px 22px, 166px 22px, 130px 10px; }
  42%, 62% { background-size: 128px 15px, 166px 22px, 166px 22px, 76px 7px; }
}
@keyframes mc-sp-fill { 0% { width: 8%; } 70%, 100% { width: 100%; } }
@keyframes mc-sp-stripe { to { background-position: 34px 0; } }
@media (max-width: 600px) {
  #loader.splash-screen::before { margin-bottom: 26px; }
  #loader.splash-screen .splash-logo { width: 112px !important; height: 112px !important; }
}
@media (prefers-reduced-motion: reduce) {
  #loader.splash-screen::before, #loader.splash-screen::after, #loader.splash-screen .splash-logo,
  #loader.splash-screen #load-spinner, #loader.splash-screen .splash-message { animation: none !important; opacity: 1; }
  #loader.splash-screen #load-spinner::before { animation: none !important; width: 60%; }
  #loader.splash-screen .splash-message::before, #loader.splash-screen .splash-message::after { animation: none !important; }
}
body.reduced-motion #loader.splash-screen .splash-logo,
body.reduced-motion #loader.splash-screen #load-spinner::before,
body.reduced-motion #loader.splash-screen::after { animation: none !important; }

/* 08 / 动效。尊重系统及酒馆的「减少动画」；保留颜色和静态状态区分。 */
@keyframes mc-leaf-rock { 0%,100% { transform: rotate(-8deg); } 50% { transform: rotate(8deg); } }
@keyframes mc-cake-ready {
  0%,65%,100% { transform: translateY(0) rotate(0); }
  77% { transform: translateY(-5px) rotate(-5deg); }
  88% { transform: translateY(0) scale(1.05,.93); }
}
@keyframes mc-box-rock { 0%,100% { transform: rotate(0); } 30% { transform: rotate(-9deg); } 70% { transform: rotate(7deg); } }
@keyframes mc-cloche { 0%,100% { filter: drop-shadow(0 0 0 #71a68b00); } 50% { filter: drop-shadow(0 0 5px #71a68b70); } }
body.reduced-motion :is(#send_form, #send_but, #mes_stop, #mes_continue, #mes_impersonate, #options_button, #extensionsMenuButton, .drawer-icon),
body.reduced-motion #send_form::after,
body.reduced-motion #chat .avatar::after {
  animation: none !important; transition: none !important;
}
@media (prefers-reduced-motion: reduce) {
  #send_form, #send_form::after, #send_but, #mes_stop, #mes_continue, #mes_impersonate, #options_button, #extensionsMenuButton,
  #chat .avatar::after, #top-settings-holder .drawer-icon { animation: none !important; transition: none !important; }
}

